"""Versioned, eight-book ZAF library; never treats an outline as accepted content."""
import html,json,re
from pathlib import Path
from zaf_dossier import render_markdown
from zaf_context_figures import figure as context_figure
from zaf_outcome_figures import figure as outcome_figure
from zaf_capability_figures import figure as capability_figure
L=json.loads((Path(__file__).resolve().parents[1]/'content/zaf_library.json').read_text())
def e(x):return html.escape(str(x),quote=True)
def badge(state,fr):
 labels={'draft':('Working draft','Brouillon de travail'),'planned':('Planned','Planifié'),'review':('In review','En revue'),'accepted':('Accepted','Accepté'),'deprecated':('Deprecated','Déprécié'),'withdrawn':('Withdrawn','Retiré')}
 return '<span class="volume-status status-'+state+'">'+labels[state][1 if fr else 0]+'</span>'
def graphic(kind,lang):
 fr=lang=='fr';uid='library-'+kind
 if kind=='institution':
  title='Institutional responsibility before engineering' if not fr else 'Responsabilité institutionnelle avant ingénierie'
  labels=(['Institutional mandate','Purpose · authority · outcomes','Business and data owners','Capabilities · decisions · information','Engineering implementation','Architecture · standards · operations'] if not fr else ['Mandat institutionnel','Finalité · autorité · résultats','Responsables métier et données','Capacités · décisions · information','Réalisation technique','Architecture · standards · exploitation'])
  desc=('Authority and intended outcomes constrain capability ownership, which then guides engineering. Arrows express decision inputs, not deployed components.' if not fr else 'Autorité et résultats orientent responsabilités et capacités, qui guident l’ingénierie. Les flèches représentent des entrées de décision, pas des composants déployés.')
 else:
  title='From Book I to the engineering library' if not fr else 'Du Livre I à la bibliothèque d’ingénierie'
  labels=(['Book I · Institutional Architecture','Mandate · capabilities · ownership','Book II · Engineering Architecture','Reference views · platform responsibilities','Books III–VIII · Delivery and operation','Rules · guides · handbooks · reliability'] if not fr else ['Livre I · Architecture institutionnelle','Mandat · capacités · responsabilités','Livre II · Architecture d’ingénierie','Vues de référence · plateformes','Livres III–VIII · Réalisation et exploitation','Règles · guides · manuels · fiabilité'])
  desc=('Institutional decisions feed engineering design. Standards and handbooks turn the design into repeatable delivery and operations; implementation evidence informs later architecture revisions.' if not fr else 'Les décisions institutionnelles alimentent la conception. Standards et manuels soutiennent réalisation et exploitation ; leurs preuves alimentent les révisions.')
 boxes=''
 for i in range(3):
  y=25+i*155;boxes+=f'<rect x="30" y="{y}" width="740" height="110" rx="5" class="dossier-node"/><text x="55" y="{y+40}" class="library-figure-title">{e(labels[i*2])}</text><text x="55" y="{y+77}" class="library-figure-sub">{e(labels[i*2+1])}</text>'
 svg=f'<svg viewBox="0 0 800 470" role="img" aria-labelledby="{uid}-title {uid}-desc"><title id="{uid}-title">{e(title)}</title><desc id="{uid}-desc">{e(desc)}</desc><defs><marker id="{uid}-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0 10 5 0 10z" fill="currentColor"/></marker></defs><path d="M400 135v35M400 290v35" stroke="currentColor" stroke-width="2" marker-end="url(#{uid}-arrow)"/>{boxes}</svg>'
 return '<figure class="dossier-figure"><div class="dossier-figure-label">'+e(title)+'</div><div class="dossier-graphic" tabindex="0" role="region" aria-label="'+e(title)+'">'+svg+'</div><figcaption>'+e(desc)+'</figcaption></figure>'
def section_body(lang,doc=None):
 doc=doc or L['firstSection'];text=doc['body'][lang];out=[]
 for piece in re.split(r'(\{\{figure:(?:institution|handoff|context|traceability|outcomes|service-value|capability-map|value-handoffs)\}\})',text):
  match=re.fullmatch(r'\{\{figure:(institution|handoff|context|traceability|outcomes|service-value|capability-map|value-handoffs)\}\}',piece)
  out.append((capability_figure(match.group(1),lang) if match.group(1) in ['capability-map','value-handoffs'] else outcome_figure(match.group(1),lang) if match.group(1) in ['outcomes','service-value'] else context_figure(match.group(1),lang) if match.group(1) in ['context','traceability'] else graphic(match.group(1),lang)) if match else render_markdown(piece,lang,doc.get('number',1)))
 if doc.get('number')==4:
  out.append('<h3>'+('Références de lecture' if lang=='fr' else 'Reading references')+'</h3><ul class="reference-list"><li><a href="https://www.omg.org/bawg/business_architecture_overview.htm" rel="noopener noreferrer">OMG · Business Architecture Overview</a></li><li><a href="https://www.tmforum.org/oda/business-architecture/value-stream-framework/" rel="noopener noreferrer">TM Forum · Value Stream Framework</a></li></ul>')
 return ''.join(out)
def metadata(fr,doc,version,status):
 return '<div class="document-meta"><span>'+e(doc)+'</span><span>v'+e(version)+'</span>'+badge(status,fr)+'<span>6 Nov 2026</span><span>Elvis Ndayishimiye · Zawatu</span></div>'
def publish(lang,page,hero,section,link,cta):
 fr=lang=='fr';title='ZAF · Bibliothèque d’architecture et d’ingénierie' if fr else 'ZAF · Architecture & Engineering Library'
 intro=('Huit livres reliés, développés et révisés progressivement. La méthode institutionnelle guide l’architecture, les standards, la réalisation et l’exploitation.' if fr else 'Eight connected books, developed and revised progressively. Institutional purpose guides architecture, standards, implementation and operations.')
 progress=('Livre I actif : sections 01 à 04 rédigées en brouillon. Les autres sections sont planifiées. La structure du Livre II est définie par le fondateur ; les autres sommaires sont proposés.' if fr else 'Book I is active: Sections 01–04 have working drafts. Other sections are planned. Book II’s structure is founder-defined; the other contents are proposed outlines.')
 body=hero('ZAF / '+('BIBLIOTHÈQUE VIVANTE' if fr else 'LIVING LIBRARY'),title,intro)
 body+=section(metadata(fr,'ZAF-LIB',L['version'],'draft')+'<div class="library-intro"><h2>'+('Une bibliothèque, une progression maîtrisée.' if fr else 'One library. A deliberate sequence.')+'</h2><p>'+progress+'</p><div class="dossier-actions">'+link('zaf/books/book-i/',('Ouvrir le Livre I ↗' if fr else 'Open Book I ↗'),'solid')+link('zaf/governance/',('Règles de publication ↗' if fr else 'Publication rules ↗'),'text-link')+'</div></div><ol class="volume-list">'+''.join('<li>'+link('zaf/books/'+b['slug']+'/', '<span class="volume-roman">'+b['roman']+'</span><span class="volume-copy"><span class="eyebrow">'+('LIVRE ' if fr else 'BOOK ')+b['roman']+'</span><h2>'+e(b['title'][lang])+'</h2><p>'+e(b['summary'][lang])+'</p></span><span class="volume-state">'+badge(b['status'],fr)+'<span>'+str(len(b['sections']))+(' sections' if fr else ' sections')+'</span><span aria-hidden="true">↗</span></span>')+'</li>' for b in L['books'])+'</ol>')
 body+=section('<div class="review-grid"><div><h2>'+('Comment lire ZAF' if fr else 'How to read ZAF')+'</h2><p>'+('Architecture : pourquoi et quelles responsabilités. Standards : quelles règles vérifier. Guides : comment réaliser. Manuels : comment développer, sécuriser et exploiter. Fiabilité : quels résultats de service maintenir.' if fr else 'Architecture explains why and who owns what. Standards define verifiable rules. Guides explain implementation. Handbooks support development, security and operations. Reliability connects service outcomes to sustainable engineering.')+'</p>'+link('zaf/governance/',('Voir la méthode éditoriale ↗' if fr else 'Read the editorial method ↗'),'text-link')+'</div><div><h2>'+('Étude et documents associés' if fr else 'Reference study and supporting material')+'</h2><p>'+('L’étude illustrative précédente reste disponible comme document d’application distinct des huit livres.' if fr else 'The earlier illustrative dossier remains available as supporting application material, separate from the eight books.')+'</p>'+link('zaf/reference-study/',('Ouvrir l’étude de référence ↗' if fr else 'Open the reference study ↗'),'text-link')+'<p>'+link('zaf/changelog/',('Historique des versions ↗' if fr else 'Release history ↗'),'text-link')+'</p></div></div>','soft')
 page('zaf/',title,intro,body)
 for b in L['books']:
  n=b['roman'];booktitle=('Livre ' if fr else 'Book ')+n+' · '+b['title'][lang]
  structure=('Structure du Livre II conservée selon les 15 sections définies par le fondateur.' if fr else 'Book II retains the founder-defined 15-section structure.') if n=='II' else ('Sommaire proposé pour développement progressif.' if fr else 'Proposed contents for sequential development.')
  statusnote=(progress if n=='I' else ('Ce livre est planifié. Les titres ci-dessous définissent le périmètre proposé ; aucun corps de standard accepté n’est publié ici.' if fr else 'This book is planned. The entries below define its intended scope; no accepted standard text is published here.'))
  contents='<p class="library-breadcrumb">'+link('zaf/',('← Bibliothèque ZAF' if fr else '← ZAF library'),'text-link')+'</p>'+metadata(fr,'ZAF-'+n,'0.4.0' if n=='I' else '0.0.0',b['status'])+'<p class="method-note">'+statusnote+'</p><p>'+structure+'</p>'
  if n=='I':contents+='<div class="dossier-actions">'+link('zaf/books/book-i/institutional-vision/',('Lire la section 01 ↗' if fr else 'Read Section 01 ↗'),'solid')+'</div>'
  contents+='<ol class="book-sections">'
  for s in b['sections']:
   label=f'{s["number"]:02d} · '+e(s['title'][lang]);text='<h2>'+label+'</h2>'
   if s['status']=='draft':text=link('zaf/books/book-i/'+s['slug']+'/',text,'section-title-link')
   note=('Document à rédiger et à revoir ; ce titre n’est pas une règle applicable.' if fr else 'Body text and review are pending; a heading is not an applicable rule.') if s['status']=='planned' else ('Brouillon de cette section disponible pour revue.' if fr else 'This section’s working draft is available for review.')
   if n=='II' and s['number']==8:note+=(' Applicabilité conditionnée à une décision d’adoption de Kubernetes.' if fr else 'Applicability is conditional on an approved Kubernetes adoption decision.')
   contents+='<li id="section-'+str(s['number']).zfill(2)+'"><div class="book-section-meta"><span>'+s['id']+'</span>'+badge(s['status'],fr)+'</div>'+text+'<p>'+note+'</p></li>'
  contents+='</ol>'
  boundary=('Ce livre définit les décisions d’architecture. Les règles vérifiables appartiennent au Livre III ; les procédures détaillées aux guides et manuels.' if fr else 'This volume defines architecture decisions. Verifiable engineering rules belong in Book III; detailed procedures belong in the guides and handbooks.') if n=='II' else ('Chaque section sera développée avec un objectif, un périmètre, des responsabilités, des figures utiles, des décisions et des preuves de validation.' if fr else 'Each section will be developed with purpose, scope, responsibilities, useful figures, decisions and validation evidence.')
  contents+='<p class="method-note">'+boundary+'</p>'
  page('zaf/books/'+b['slug']+'/',booktitle,b['summary'][lang],hero('ZAF / '+('LIVRE ' if fr else 'BOOK ')+n,e(b['title'][lang]),b['summary'][lang])+section(contents,'book-contents'))
 # Publish only drafted sections; planned entries remain anchored in the contents.
 b=L['books'][0]
 for s in b['sections']:
  if s['status']!='draft':continue
  x=L['firstSection'] if s['number']==1 else L['draftSections'][s['id']]
  subheads=re.findall(r'^## (.+)$',x['body'][lang],re.M)
  chaptertitle=s['title'][lang]
  sidebar='<aside class="dossier-sidebar"><nav class="dossier-toc" aria-label="'+('Sections du Livre I' if fr else 'Book I sections')+'">'+link('zaf/books/book-i/',('Livre I · Sommaire' if fr else 'Book I · Contents'),'dossier-home')+'<ol>'+''.join('<li>'+link('zaf/books/book-i/'+(q['slug']+'/' if q['status']=='draft' else '#section-'+str(q['number']).zfill(2)),f'<span>{q["number"]:02d}</span> '+e(q['title'][lang]),'is-current' if q['number']==s['number'] else '')+'</li>' for q in b['sections'])+'</ol></nav></aside>'
  toc='<details class="chapter-contents" open><summary>'+('Dans cette section' if fr else 'In this section')+'</summary><ol>'+''.join('<li><a href="#section-'+re.match(r'(\d+\.\d+)',h).group(1).replace('.','-')+'">'+e(h)+'</a></li>' for h in subheads)+'</ol></details>'
  subtitle=('Brouillon institutionnel avec preuves, décisions et critères de revue.' if fr else 'Institutional working draft with evidence, decisions and review criteria.')
  chapter=hero('ZAF / '+('LIVRE I · SECTION ' if fr else 'BOOK I · SECTION ')+str(s['number']).zfill(2),e(chaptertitle),subtitle).replace('page-hero wrap','page-hero wrap dossier-chapter-hero')
  pagination='<nav class="chapter-pagination">'
  if s['number']>1:
   prev=b['sections'][s['number']-2]
   if prev['status']=='draft':pagination+=link('zaf/books/book-i/'+prev['slug']+'/',('← Section précédente' if fr else '← Previous section'),'text-link')
  pagination+=link('zaf/books/book-i/',('Sommaire du Livre I' if fr else 'Book I contents'),'text-link')
  if s['number']<len(b['sections']):
   nxt=b['sections'][s['number']]
   if nxt['status']=='draft':pagination+=link('zaf/books/book-i/'+nxt['slug']+'/',('Section suivante →' if fr else 'Next section →'),'text-link')
  pagination+=link('zaf/governance/',('Règles de revue ↗' if fr else 'Review rules ↗'),'text-link')+'</nav>'
  chapter+='<div class="dossier-layout wrap">'+sidebar+'<article class="dossier-chapter">'+metadata(fr,s['id'],x['version'],'draft')+toc+section_body(lang,x)+pagination+'</article></div>'
  page('zaf/books/book-i/'+s['slug']+'/',chaptertitle,subtitle,chapter)
 publish_governance(lang,page,hero,section,link)

def publish_governance(lang,page,hero,section,link):
 fr=lang=='fr'
 headings=(['1. Statut et autorité','2. Contrat documentaire','3. Règles normatives et preuves','4. Versions et changements','5. Acceptation d’un livre','6. Références et maturité internationale'] if fr else ['1. Status and authority','2. Documentation contract','3. Normative rules and evidence','4. Versions and change control','5. Book acceptance gate','6. References and international maturity'])
 paras=(['ZAF est une bibliothèque indépendante éditée par Elvis Ndayishimiye pour Zawatu. L’édition actuelle est un brouillon public. Aucune revue indépendante, adoption externe ou accréditation n’est annoncée. Une publication ne constitue pas une acceptation.','Une section décrit objectif, périmètre, acteurs, exigences, preuves disponibles, analyse, recommandations, figures et limites, décisions, livrables, vérifications, exceptions et références croisées. Les exemples sont distingués des règles applicables.','Le Livre III distinguera Obligatoire, Recommandé, Facultatif, Exemple et Liste de vérification. Toute règle obligatoire aura un identifiant stable, une applicabilité, une justification, une preuve vérifiable, un responsable et une procédure d’exception. Ces règles ne s’appliquent à une institution qu’après adoption explicite.','Bibliothèque, livre et section ont des versions distinctes. Une modification enregistre demande, motif, auteur, impacts, preuves et décision. Une correction éditoriale ne change pas le sens ; une règle nouvelle ou incompatible exige une revue de compatibilité et, si nécessaire, une migration. Les anciennes versions acceptées doivent rester identifiables.','Terminer la rédaction ne suffit pas. Les sections nécessaires, définitions, renvois, figures et preuves doivent être examinés. Les règles normatives doivent être vérifiables ; les procédures doivent être exercées selon leur périmètre. L’éditeur enregistre les réviseurs réels et leurs constats avant décision d’acceptation. Aucune personne n’est présentée comme réviseur sans participation.','La trajectoire vise une bibliothèque utile au-delà de la région : rédaction traçable, revue qualifiée, pilotes autorisés, résultats documentés, versions maintenues et retours externes. Les références ci-dessous sont bibliographiques ; aucune conformité clause par clause n’est encore déclarée.'] if fr else ['ZAF is an independent library edited by Elvis Ndayishimiye for Zawatu. The current edition is a public working draft. No independent review, external adoption or accreditation is claimed. Publication does not constitute acceptance.','A section records purpose, scope, stakeholders, requirements, available evidence, assessment, recommendations, useful figures and their limits, decisions, artifacts, verification, exceptions and cross-references. Examples are distinguished from applicable rules.','Book III will distinguish Mandatory, Recommended, Optional, Example and Compliance Checklist content. Every mandatory rule needs a stable ID, applicability, rationale, verifiable evidence, accountable owner and exception route. ZAF rules apply to an institution only through explicit adoption.','The library, each book and each section have separate versions. A change records its request, rationale, author, impact, evidence and decision. Editorial corrections preserve meaning; new or incompatible rules require compatibility review and migration guidance where needed. Earlier accepted versions must remain identifiable.','Finishing the text is insufficient. Required sections, definitions, links, figures and evidence must be reviewed. Normative rules must be verifiable; operating procedures must be exercised within their stated scope. The editor records actual reviewers and findings before an acceptance decision. Nobody is presented as a reviewer without participation.','The international ambition is pursued through traceable writing, qualified review, authorized pilots, documented outcomes, maintained releases and external feedback. References below are bibliographic; no clause-by-clause conformance is currently asserted.'])
 states=[('Planned','Planifié','Outline only; no accepted rule text.','Sommaire uniquement ; aucun texte normatif accepté.'),('Working draft','Brouillon','Written material open to substantive change.','Texte rédigé susceptible de modifications.'),('In review','En revue','Named reviewers examine an identified version.','Réviseurs nommés sur une version identifiée.'),('Accepted','Accepté','Recorded owner decision after required evidence.','Décision enregistrée après preuves requises.'),('Deprecated','Déprécié','A replacement and migration path are identified.','Remplacement et trajectoire identifiés.'),('Withdrawn','Retiré','Use is discontinued with a recorded reason.','Usage retiré avec motif enregistré.')]
 body=''
 for i,(h,p) in enumerate(zip(headings,paras)):
  body+='<h2>'+h+'</h2><p>'+p+'</p>'
  if i==0:body+='<div class="table-scroll"><table><thead><tr><th>'+('État' if fr else 'State')+'</th><th>'+('Signification' if fr else 'Meaning')+'</th></tr></thead><tbody>'+''.join('<tr><th scope="row">'+r[1 if fr else 0]+'</th><td>'+r[3 if fr else 2]+'</td></tr>' for r in states)+'</tbody></table></div>'
  if i==2:body+='<p class="method-note">'+('Format de règle proposé : ZAF-[LIVRE]-[DOMAINE]-[NUMÉRO]. Une liste de vérification générique ne prouve pas qu’un système l’a satisfaite.' if fr else 'Proposed rule identifier: ZAF-[BOOK]-[DOMAIN]-[NUMBER]. A generic checklist does not establish that a system has passed it.')+'</p>'
 refs=[('ISO/IEC/IEEE 42010:2022','https://www.iso.org/standard/74393.html','Architecture description; planned comparison of documentation structure.','Description d’architecture ; comparaison documentaire à développer.'),('TOGAF Standard — example template deliverables','https://help.opengroup.org/hc/en-us/articles/21726647171730-Are-There-Any-Template-Deliverables-for-the-TOGAF-Standard','Reference for architecture work-product organisation.','Référence pour l’organisation des livrables.'),('NIST Cybersecurity Framework 2.0','https://www.nist.gov/cyberframework','Reference for cybersecurity risk and governance concerns.','Référence pour les risques et la gouvernance cyber.')]
 body+='<ul class="reference-list">'+''.join('<li><a href="'+url+'" rel="noopener noreferrer">'+e(name)+'</a><p>'+e(descfr if fr else descen)+'</p></li>' for name,url,descen,descfr in refs)+'</ul>'
 body+='<h2>'+('7. Prochaine étape de rédaction' if fr else '7. Next authoring step')+'</h2><p>'+('Réviser les sections 01 à 04 du Livre I, puis développer la section 05. Le passage au Livre II dépend de la progression du Livre I ; la bibliothèque ne s’étend pas par remplissage automatique de tous les volumes.' if fr else 'Review Book I / Sections 01–04, then develop Section 05. Progress to Book II follows the Book I authoring sequence; the collection is not expanded by automatically filling every volume.')+'</p>'
 title='Gouvernance éditoriale ZAF' if fr else 'ZAF editorial governance'
 page('zaf/governance/',title,title,hero('ZAF / '+('GOUVERNANCE' if fr else 'GOVERNANCE'),title,('Statuts, versions, preuves et règles de revue.' if fr else 'Status, versions, evidence and review rules.'))+section('<article class="dossier-chapter governance-body">'+body+'</article>'))
 change=('<h2>0.5.0 · 6 novembre 2026</h2><p>Livre I / section 04 publié en brouillon 0.1.0 : capacités, responsabilités, flux de valeur, contrats de transfert, exceptions, preuves et décisions. Deux figures, huit capacités proposées, quatre étapes et sept livrables. Aucun résultat mesuré ni acceptation institutionnelle annoncé.</p><h2>0.4.0 · 6 novembre 2026</h2><p>Livre I / section 03 publié en brouillon 0.1.0 : finalité, modèle de contribution, registre de résultats, contrats de mesure, parcours, options, viabilité et revue. Deux figures et sept livrables proposés ; aucune mesure réelle ni acceptation annoncée.</p><h2>0.3.0 · 6 novembre 2026</h2><p>Livre I / section 02 publié en brouillon 0.1.0 : contexte, acteurs, préoccupations, conflits, points de vue, preuves et deux figures. Navigation entre sections et statut du livre actualisés. Aucune section n’est promue à un statut accepté.</p><h2>0.2.0 · 6 novembre 2026</h2><p>Bibliothèque de huit livres créée. Structure exacte des 15 sections du Livre II conservée. Livre I, section 01 rédigée en brouillon 0.1.0. Autres sommaires proposés et sections planifiées. Gouvernance, statuts et références publiés. Étude antérieure conservée séparément.</p><h2>Étude de référence · 5 novembre 2026</h2><p>Dossier illustratif de 15 chapitres. Cette étude est un document d’application ; elle ne constitue pas les huit livres de standards.</p>' if fr else '<h2>0.5.0 · 6 November 2026</h2><p>Published Book I / Section 04 as draft 0.1.0: capabilities, ownership, value streams, handoff contracts, exceptions, evidence and decisions. Two figures, eight proposed capabilities, four stages and seven artifacts. No measured results or institutional acceptance claimed.</p><h2>0.4.0 · 6 November 2026</h2><p>Published Book I / Section 03 as draft 0.1.0: purpose, contribution model, outcome register, measurement contracts, service journeys, options, viability and review. Two figures and seven proposed artifacts; no measured results or acceptance claimed.</p><h2>0.3.0 · 6 November 2026</h2><p>Published Book I / Section 02 as draft 0.1.0: context, stakeholders, concerns, conflicts, viewpoints, evidence and two figures. Updated section navigation and book status. No section is promoted to accepted.</p><h2>0.2.0 · 6 November 2026</h2><p>Established the eight-book library. Preserved Book II’s exact 15-section structure. Drafted Book I / Section 01 as version 0.1.0. Other outlines are proposed and their sections remain planned. Published status, governance and reference rules. Preserved the earlier study separately.</p><h2>Reference study · 5 November 2026</h2><p>Published the illustrative 15-chapter dossier. It is supporting application material, not the eight standards books.</p>')
 page('zaf/changelog/',('Historique ZAF' if fr else 'ZAF release history'),title,hero('ZAF / CHANGELOG',('Historique des versions' if fr else 'Release history'),('Évolution documentée de la bibliothèque.' if fr else 'Documented evolution of the library.'))+section(change)+section(link('zaf/',('← Bibliothèque' if fr else '← Library'),'text-link')))
